from typing import List

def parse_music(music_string: str) -> List[int]:
    mapping = {'o': 4, 'o|': 2, '.|': 1}
    tokens = music_string.split()
    return [mapping[token] for token in tokens]

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    # positive shift means circular shift right by shift digits
    shift %= n
    if shift == 0:
        return s
    return s[-shift:] + s[:-shift]

def anti_shuffle(s):
    import re
    def sort_word(w):
        return ''.join(sorted(w))
    # Split into words and spaces, preserving all spaces as separate tokens
    tokens = re.findall(r'\S+|\s+', s)
    # For each token, if it's a word (non-space), sort its characters; else keep as is
    return ''.join(sort_word(t) if not t.isspace() else t for t in tokens)

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0:
            total += val ** 2
        elif i % 4 == 0:
            total += val ** 3
        else:
            total += val
    return total

def order_by_points(numbers):
    def digit_sum(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            digits[0] = -digits[0]
        return sum(digits)
    return sorted(numbers, key=digit_sum)

def total_match(lst1, lst2):
    if sum(len(s) for s in lst1) <= sum(len(s) for s in lst2):
        return lst1
    else:
        return lst2
